1311:        const _addOutputControlValues = function ( vanillaOutputBoxWrapper, collectingObject) {
        const _addOutputControlValues = function ( vanillaOutputBoxWrapper, collectingObject) {
            let errorOccurred = null;
            const chartTypeChooser = vanillaOutputBoxWrapper.querySelector( '.chartTypeChooser' );
            if ( ! chartTypeChooser ) {
                throw new Error( I18nTranslator.i18n( 'exceptions.chartTypeChooserNotFound' ) );
            }
            const chartType = chartTypeChooser.value;
            if (!chartType) {
                errorOccurred = I18nTranslator.i18n('visualization.noChartTypeChosen');
            }

            const dimensions = [];
            vanillaOutputBoxWrapper.querySelectorAll('.dimension').forEach( function(node, index) {
                const dimension = node.value;
                if (dimension) {
                    const valueToStore = {"name":dimension};
                    _addAdditionalOptions( node.parentNode.querySelector('.aggregationOptionsControl'), valueToStore );
                    dimensions[index] = valueToStore;
                } else {
                    errorOccurred = I18nTranslator.i18n('visualization.pleaseSelectAFieldForEachDimension');
                }
            });

            if (errorOccurred !== null) {
                if ( optionalUserInfoFunction ) {
                    const mousePos = me.getCurrentMousePosition();
                    const where = 'left+' + mousePos.x + ' top+' + mousePos.y;
                    optionalUserInfoFunction(errorOccurred, 4000, {
                        position: {my: 'left top', at: where, of: 'body'},
                    });
                } else {
                    _warnUser( errorOccurred, I18nTranslator.i18n('misc.addValuesToOutputControlFailed') + ': ' + errorOccurred );
                }
            } else {
                collectingObject.chartType = chartType;
                collectingObject.dimensions = dimensions;
            }

            return errorOccurred === null;
        };
